  'guide.retail.title': 'Promotions, labels and shelves',
  'guide.retail.lede': 'Tools for a shop or boutique: promotions, sizes and colours, quick keys at the till, printed labels and shelf locations.',
  'guide.retail.s1': 'Prices → Promotions → “New promotion”: choose the kind (3 for ₱800, Buy 2 get 1 free, 10% off 6 or more), the items, the branches and when it runs.',
  'guide.retail.s2': 'A promotion’s terms never change. To change them, press “End now” (or “Call off” one that has not started) and “Copy” to make a new one.',
  'guide.retail.s3': 'Shirts or shoes in sizes and colours: in “Add product”, tick “This product comes in sizes or colours” and list the values. Every combination becomes a variant. On a product’s page, “Add sizes and colours” adds the ones it lacks.',
  'guide.retail.s4': 'Products → Quick keys: put up to 48 items on the till’s Sell screen as buttons.',
  'guide.retail.s5': 'Products → Labels: pick items and copies, the branch and a layout, then “Print labels”. An item without a barcode prints its SKU; “Make barcode” on its page gives it a store barcode.',
  'guide.retail.s6': 'Inventory → Stock & value: type where an item sits (e.g. A3-2) in its Shelf field. Count sheets list items in shelf order, and “All branches” shows every branch’s stock side by side.',
  'guide.retail.t1': 'The till gives the customer the best promotion, one per line. A line with SC/PWD, its own discount or an approved price is never promoted.',
  'guide.retail.t2': 'Reports → Promotions shows the discount each promotion gave and its sales; Reports → Sizes and colours totals sales by size or by colour.',
  'guide.retail.t3': 'At the till, type 5* before scanning to sell 5 of an item.',
