  'guide.salon.title': 'Appointments, packages and staff',
  'guide.salon.lede': 'For a salon, spa or barber shop: the people who do the work, the calendar, services and prepaid packages, and each client’s history.',
  'guide.salon.s1': 'Under Appointments → Staff, press “Add staff member” for each person who performs services (they need not sign in). Give each a calendar colour, their commission % and their weekly hours.',
  'guide.salon.s2': 'Under Products, add each service with the kind “Service” and its duration in minutes. On the service’s page, “Supplies used” lists what it takes from stock.',
  'guide.salon.s3': 'Book from Appointments → Calendar: press an empty time in a staff member’s column, or “New appointment”. Pick the customer or type a guest’s name, then each service with its staff and time; the free times are suggested.',
  'guide.salon.s4': 'When the client comes in, open the appointment and press “Mark arrived”. When they are done, ring it up at the till; the appointment then links to its sale.',
  'guide.salon.s5': 'Sell packages (prepaid sessions) as products of the kind “Package”: choose the services and sessions on its page. Sessions are used at the till, and the customer’s page shows what is left.',
  'guide.salon.s6': 'Reports → Salon has the commissions per staff member, the packages sold, used and still owed, tips by staff, the tips still owed, and the supplies services used.',
  'guide.salon.t1': 'Outside a staff member’s hours or in their time off, booking asks first; “Book anyway” squeezes the client in. A staff member is never booked twice at once. Archiving someone or adding time off over their open bookings lists those bookings first: reassign or cancel them, or press “Keep the bookings and archive” (or “… and add the time off”) to sort them out later.',
  'guide.salon.t2': 'With the reminder ticked (the default when the customer has an email), the customer gets one email about a day before.',
  'guide.salon.t3': 'Service notes on the customer’s page keep formulas and preferences. Notes can hold health details: keep only what the service needs. They are never shown to API keys or to Tilvara support.',
  'guide.salon.t4': 'Front Desk and Stylist are ready-made roles under Team. Commission rates show only to those who manage staff.',
  'guide.salon.t5': 'Tips are owed to staff, not sales. Reports → Salon → Tips shows what was taken, given back on voids and paid out from the drawers, and what is still owed.',
  // ---- hotels, resorts and transient houses (ADR-0023) ----



