  'guide.pharmacy.title': 'Medicines, prescriptions and batches',
  'guide.pharmacy.lede': 'For a pharmacy or drugstore: medicines with generic names and classes, receiving batches with lot codes, prescriptions and what is left to dispense, the prescription and dangerous drugs books, batch trace and holds, and never selling expired stock.',
  'guide.pharmacy.s1': 'Under Products, add each brand as a product and tick “A medicine”: its class (over the counter, prescription, antibiotic or dangerous drug), generic name, strength and dosage form. A medicine keeps expiry dates.',
  'guide.pharmacy.s2': 'Sell by the box, strip and piece: make each a product and link them under the box’s and the strip’s pages (Packs and pieces (tingi)). A sale short of tablets opens a strip, and a box if needed, by itself.',
  'guide.pharmacy.s3': 'Receive deliveries with the expiry date and the lot code of each batch (Purchasing, or a stock adjustment). A medicine is refused without its lot code.',
  'guide.pharmacy.s4': 'At the till a prescription medicine or antibiotic needs a prescription: record it there, or here under Pharmacy → New prescription ahead of time. Quantities are in pieces; any brand with the same generic fills it.',
  'guide.pharmacy.s5': 'Pharmacy → Prescriptions shows what is left to dispense and every sale that filled it. A prescription can be edited or voided only while nothing is dispensed on it.',
  'guide.pharmacy.s6': 'Pharmacy → Prescription book and Dangerous drugs book are the registers to print or download for each branch and period.',
  'guide.pharmacy.s7': 'For a recall, Pharmacy → Batch trace shows where a lot went (sales and customers) and what is left; Lot holds stops it from being sold until you release it.',
  'guide.pharmacy.t1': 'A pharmacy’s branches never sell expired stock (Inventory → Settings): write expired batches off from Inventory → Expiry.',
  'guide.pharmacy.t2': 'A cashier without the permission to dispense needs a pharmacist’s approval at the till; a dangerous drug needs a pharmacist with a licence on record (Pharmacy → Set-up).',
  'guide.pharmacy.t3': 'A dangerous drug is never sold offline, and its prescription is filled once, in full.',
  'guide.pharmacy.t4': 'Medicines that are VAT-exempt by law are set up with the VAT-exempt tax category. SC/PWD discounts on medicine record the purchase booklet.',
  'guide.pharmacy.t5': 'Pharmacist and Pharmacy Assistant are ready-made roles under Team. The rules here are assumptions for your pharmacist-in-charge to check.',
