  'guide.retail.title': 'Promo, label at estante',
  'guide.retail.lede': 'Mga gamit para sa tindahan o boutique: mga promo, size at kulay, quick key sa till, naka-print na label at lokasyon sa estante.',
  'guide.retail.s1': 'Mga presyo → Mga promo → “Bagong promo”: piliin ang uri (3 sa halagang ₱800, Bumili ng 2 libre ang 1, 10% bawas sa 6 pataas), ang mga item, ang mga branch at kung kailan ito tatakbo.',
  'guide.retail.s2': 'Hindi nababago ang mga tuntunin ng promo. Para baguhin, pindutin ang “Tapusin ngayon” (o “Huwag nang ituloy” kung hindi pa nagsisimula) at “Kopyahin” para gumawa ng bago.',
  'guide.retail.s3': 'Mga shirt o sapatos na may size at kulay: sa “Magdagdag ng produkto”, i-tsek ang “May mga size o kulay ang produktong ito” at ilista ang mga value. Bawat kombinasyon ay nagiging variant. Sa pahina ng produkto, idinadagdag ng “Magdagdag ng size at kulay” ang mga kulang.',
  'guide.retail.s4': 'Mga produkto → Mga quick key: maglagay ng hanggang 48 item bilang mga button sa Sell screen ng till.',
  'guide.retail.s5': 'Mga produkto → Mga label: pumili ng mga item at kopya, ang branch at layout, saka “I-print ang mga label”. Ang item na walang barcode ay ipi-print ang SKU nito; binibigyan ito ng “Gumawa ng barcode” sa pahina nito ng sariling barcode ng tindahan.',
  'guide.retail.s6': 'Imbentaryo → Stock at halaga: i-type kung saan nakalagay ang item (hal. A3-2) sa field nitong Estante. Nakaayos ayon sa estante ang mga count sheet, at ipinapakita ng “Lahat ng branch” ang stock ng bawat branch nang magkakatabi.',
  'guide.retail.t1': 'Ibinibigay ng till sa customer ang pinakamagandang promo, isa bawat linya. Hindi kailanman may promo ang linyang may SC/PWD, sariling diskwento o inaprubahang presyo.',
  'guide.retail.t2': 'Ipinapakita ng Mga ulat → Mga promo ang bawas na naibigay ng bawat promo at ang benta nito; binubuod ng Mga ulat → Size at kulay ang benta ayon sa size o kulay.',
  'guide.retail.t3': 'Sa till, i-type ang 5* bago mag-scan para magbenta ng 5 sa isang item.',
