  'guide.salon.title': 'Appointment, package at staff',
  'guide.salon.lede': 'Para sa salon, spa o barberya: ang mga gumagawa ng trabaho, ang kalendaryo, mga serbisyo at bayad-na-unang package, at kasaysayan ng bawat kliyente.',
  'guide.salon.s1': 'Sa Mga appointment → Staff, pindutin ang “Magdagdag ng staff” para sa bawat gumagawa ng serbisyo (hindi nila kailangang mag-sign in). Bigyan ang bawat isa ng kulay sa kalendaryo, komisyon % at oras bawat linggo.',
  'guide.salon.s2': 'Sa Mga produkto, idagdag ang bawat serbisyo na uring “Serbisyo” at ang tagal nito sa minuto. Sa pahina ng serbisyo, nakalista sa “Gamit na supplies” ang kinukuha nito sa stock.',
  'guide.salon.s3': 'Mag-book sa Mga appointment → Kalendaryo: pindutin ang bakanteng oras sa hanay ng staff, o “Bagong appointment”. Piliin ang customer o i-type ang pangalan ng bisita, saka bawat serbisyo kasama ang staff at oras; may mungkahing bakanteng oras.',
  'guide.salon.s4': 'Pagdating ng kliyente, buksan ang appointment at pindutin ang “Markahang dumating”. Kapag tapos na, singilin ito sa till; mali-link na ang appointment sa benta nito.',
  'guide.salon.s5': 'Magbenta ng package (bayad-na-unang session) bilang produktong uring “Package”: piliin sa pahina nito ang mga serbisyo at session. Ginagamit ang session sa till, at makikita sa pahina ng customer ang natitira.',
  'guide.salon.s6': 'Nasa Mga ulat → Salon ang komisyon bawat staff, ang mga package na nabenta, nagamit at utang pa, tip bawat staff, ang tip na hindi pa naibibigay, at ang mga supply na nagamit ng serbisyo.',
  'guide.salon.t1': 'Sa labas ng oras ng staff o sa day off nila, nagtatanong muna ang booking; isinisingit ng “I-book pa rin” ang kliyente. Hindi kailanman nabu-book nang dalawang beses nang sabay ang isang staff. Kapag ina-archive ang isang staff o dinadagdagan ng day off sa oras ng bukas niyang booking, ililista muna ang mga ito: ibigay sa iba o kanselahin, o pindutin ang “Hayaan ang mga booking at i-archive” (o “… at idagdag ang day off”) para ayusin mamaya.',
  'guide.salon.t2': 'Kapag naka-tsek ang paalala (default kapag may email ang customer), makakatanggap ang customer ng isang email mga isang araw bago.',
  'guide.salon.t3': 'Nasa pahina ng customer ang tala sa serbisyo para sa formula at gusto. Maaaring may detalye sa kalusugan ang tala: itago lang ang kailangan ng serbisyo. Hindi ito ipinapakita sa mga API key o sa support ng Tilvara.',
  'guide.salon.t4': 'Handa nang role sa Team ang Front Desk at Stylist. Ang mga namamahala ng staff lang ang nakakakita ng rate ng komisyon.',
  'guide.salon.t5': 'Para sa staff ang tip, hindi benta. Ipinapakita ng Mga ulat → Salon → Tip ang natanggap, ibinalik dahil sa void at ibinigay mula sa drawer, at ang hindi pa naibibigay.',
